from pathlib import Path
import torch,json
p=Path('/workspace/tensor_language/basis_aligned/polynomial_causal/direct_tensor_match');torch.set_num_threads(2);torch.set_grad_enabled(False);rows=torch.load(p/'MIDPOINT_CALIBRATION_ROWS_V1.pt',weights_only=True);n=rows['n'].flatten(0,1).double();m=rows['m'].flatten(0,1).double();source=torch.load(p/'MIDPOINT_SIGNED_BLOCK_PROGRAM_V1.pt',weights_only=True);e={k:v.double() for k,v in source['program'].items()};K=source['teacher_blocks'].double();truth=torch.einsum('bi,gij,bj->bg',n,K,m);pred=((n@e['directions'])*(m@e['directions']))@e['readout'];error=pred-truth;truthcenter=truth-truth.mean(0);meanerror=error.mean(0);centererror=error-meanerror;energy=truthcenter.square().sum(0);old=(error.square().sum(0)/energy).sqrt();new=(centererror.square().sum(0)/energy).sqrt();fraction=len(n)*meanerror.square()/error.square().sum(0);corr=[]
for g in range(4):
 a=centererror[:,2*g];b=centererror[:,2*g+1];corr.append(float((a@b)/(a.norm()*b.norm())))
result=dict(full_error_over_centered_target=old.tolist(),mean_corrected_error_over_centered_target=new.tolist(),constant_fraction_of_squared_error=fraction.tolist(),positive_negative_centered_error_cosines=corr,scope='Originalcalibration per-block error audit. Own-calibration mean correction is data-informed; it changes removals relative to zero but cancels in same-token swaps. Opposing block errors can cancel in netfeature. No native individualblock intervention validated.')
out=p/'MIDPOINT_BLOCK_ERROR_AUDIT_V1.json';assert not out.exists();out.write_text(json.dumps(result,indent=2)+'\n');source['program']['offset']=pred.mean(0).float();source['true_block_means']=truth.mean(0);source['scope']=result['scope'];torch.save(source,p/'MIDPOINT_CENTERED_BLOCK_PROGRAM_V1.pt');print(json.dumps(result,indent=2))
